  created_at timestamp with time zone NOT NULL,
  updated_at timestamp with time zone NOT NULL,
  CONSTRAINT shifts_pkey PRIMARY KEY (id),
  CONSTRAINT shifts_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE INDEX shifts_is_active ON shifts USING btree (is_active);
CREATE INDEX shifts_is_default ON shifts USING btree (is_default);
CREATE INDEX shifts_organization_id ON shifts USING btree (organization_id);
CREATE UNIQUE INDEX shifts_organization_id_name ON shifts USING btree (organization_id, name);

CREATE TABLE users (
  id uuid NOT NULL,
  organization_id uuid NOT NULL,
  name character varying(255) NOT NULL,
  email character varying(255) NOT NULL,
  password character varying(255) NOT NULL,
  role enum_users_role NOT NULL DEFAULT 'EMPLOYEE'::enum_users_role,
  manager_id uuid,
  employee_id character varying(255),
  department character varying(255),
  date_of_birth date,
  hire_date date,
  is_active boolean DEFAULT true,
  last_login timestamp with time zone,
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamp with time zone NOT NULL,
  updated_at timestamp with time zone NOT NULL,
  designation character varying(255),
  phone character varying(255),
  two_factor_enabled boolean DEFAULT false,
  two_factor_secret character varying(255),
  CONSTRAINT users_pkey PRIMARY KEY (id),
  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_email_key1 UNIQUE (email),
  CONSTRAINT users_manager_id_fkey FOREIGN KEY (manager_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT users_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE INDEX idx_users_active_org_manager ON users USING btree (organization_id, manager_id) WHERE is_active;
CREATE INDEX idx_users_org_lower_email ON users USING btree (organization_id, lower((email)::text));
CREATE INDEX users_email ON users USING btree (email);
CREATE UNIQUE INDEX users_employee_id_organization_id ON users USING btree (employee_id, organization_id);
CREATE INDEX users_manager_id ON users USING btree (manager_id);
CREATE INDEX users_organization_id ON users USING btree (organization_id);

CREATE TABLE wfh_requests (
  id uuid NOT NULL,
  organization_id uuid NOT NULL,
  user_id uuid NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  is_half_day boolean DEFAULT false,
  half_day_type enum_wfh_requests_half_day_type,
  reason text NOT NULL,
  status enum_wfh_requests_status NOT NULL DEFAULT 'PENDING'::enum_wfh_requests_status,
  approved_by uuid,
  approved_at timestamp with time zone,
  rejection_reason text,
  created_at timestamp with time zone NOT NULL,
  updated_at timestamp with time zone NOT NULL,
  CONSTRAINT wfh_requests_pkey PRIMARY KEY (id),
  CONSTRAINT wfh_requests_approved_by_fkey FOREIGN KEY (approved_by) REFERENCES users(id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT wfh_requests_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT wfh_requests_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE INDEX idx_wfh_requests_active_range ON wfh_requests USING btree (user_id, start_date, end_date) WHERE (status = ANY (ARRAY['PENDING'::enum_wfh_requests_status, 'APPROVED'::enum_wfh_requests_status]));
CREATE INDEX idx_wfh_requests_pending_org ON wfh_requests USING btree (organization_id, created_at) WHERE (status = 'PENDING'::enum_wfh_requests_status);
CREATE INDEX wfh_requests_organization_id ON wfh_requests USING btree (organization_id);
CREATE INDEX wfh_requests_start_date_end_date ON wfh_requests USING btree (start_date, end_date);
CREATE INDEX wfh_requests_user_id_start_date_end_date ON wfh_requests USING btree (user_id, start_date, end_date);

CREATE TABLE workforce_reports (
  id uuid NOT NULL,
  organization_id uuid NOT NULL,
  report_type text NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  scope_manager_id uuid,
  requested_by uuid,
  status text NOT NULL DEFAULT 'PENDING'::text,
  summary jsonb,
  row_count integer,
  content text,
  error text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  completed_at timestamp with time zone,
  CONSTRAINT workforce_reports_pkey PRIMARY KEY (id),
  CONSTRAINT workforce_reports_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE,
  CONSTRAINT workforce_reports_requested_by_fkey FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT workforce_reports_scope_manager_id_fkey FOREIGN KEY (scope_manager_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT workforce_reports_check CHECK ((period_start <= period_end)),
  CONSTRAINT workforce_reports_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'READY'::text, 'FAILED'::text])))
);
CREATE INDEX idx_workforce_reports_org_created ON workforce_reports USING btree (organization_id, created_at DESC);
CREATE UNIQUE INDEX uq_workforce_reports_scheduled ON workforce_reports USING btree (organization_id, report_type, period_start, period_end) WHERE ((requested_by IS NULL) AND (scope_manager_id IS NULL));
